 if (pharmflow_expiry_private.gs1_source_locks(o.payload,c.facts)->>'batch')::boolean and (p_correction->>'batch_no') is not distinct from (o.payload->>'batch_no') then batch:=nullif(o.payload->>'batch_no','');end if;
 if qty>0 then
